 static PublicRecipe R(string id,string name,int source,bool breakfast,bool vegetarian,bool batch,string steps,string ingredients){
  var s=Sources[source];return new PublicRecipe{Source=source,Vegetarian=vegetarian,Batch=batch,Recipe=new NutritionRecipe{id="freebook:"+id,name=name,meal=breakfast?"Petit-déjeuner":"Déjeuner & dîner",portions=breakfast?2:4,
   instructions=steps+"\n\nAdaptation Mon Espace : quantités métriques, portions et accompagnements ajustés ; produits laitiers remplacés ou retirés. Valeurs nutritionnelles indicatives, à adapter aux emballages. Choisir les produits emballés déclarés sans lactose. Eau de cuisson ajustable.\n\nSource : "+s.credit+", "+s.title+" (révision "+s.revision+"). "+s.url+"\nAuteurs et historique : "+s.history+"\nRecette adaptée sous CC BY-SA 4.0 : https://creativecommons.org/licenses/by-sa/4.0/",
   ingredients=ingredients.Split(';').Select(part=>{var p=part.Split('=');return new RecipeIngredient{foodId=p[0].StartsWith("+")?"freefood:"+p[0].Substring(1):p[0],quantity=Decimal.Parse(p[1],CultureInfo.InvariantCulture)};}).ToList()}};
 }
