 internal static string[] Pack(string name){return Recipes.Where(r=>name!="Végétarien"||r.Vegetarian).Where(r=>name!="Batch cooking"||r.Batch).Select(r=>r.Recipe.id).ToArray();}
 // Import only on request. IDs and equivalent ingredient names prevent repeated copies; user edits are retained.
 internal static Dictionary<string,string> Import(SportNutritionData d,IEnumerable<string> requested){
  var map=new Dictionary<string,string>();var foods=Foods();
  foreach(var id in requested.Distinct()){
   var spec=Recipes.First(r=>r.Recipe.id==id);var existing=d.recipes.FirstOrDefault(r=>r.id==id||String.Equals(r.name.Trim(),spec.Recipe.name,StringComparison.OrdinalIgnoreCase));
   if(existing!=null){map[id]=existing.id;continue;}
   var copy=SportNutrition.Copy(spec.Recipe);
   foreach(var i in copy.ingredients){var source=foods.First(f=>f.id==i.foodId);var match=d.foods.FirstOrDefault(f=>f.id==source.id)??d.foods.FirstOrDefault(f=>f.unit==source.unit&&String.Equals(f.name.Trim(),source.name.Trim(),StringComparison.OrdinalIgnoreCase));if(match==null){match=SportNutrition.Copy(source);d.foods.Add(match);}i.foodId=match.id;}
   d.recipes.Add(copy);map[id]=copy.id;
  }return map;
 }
 internal static List<MenuEntry> Suggest(SportNutritionData d,string pack,DateTime start,int days){var draft=SportNutrition.Copy(d);var ids=Import(draft,Pack(pack)).Values.ToHashSetCompat();draft.recipes=draft.recipes.Where(r=>ids.Contains(r.id)).ToList();return SportNutrition.SuggestMenu(draft,start,days);}
 static HashSet<string> ToHashSetCompat(this IEnumerable<string> values){return new HashSet<string>(values);}
}

internal sealed partial class ModernWorkspace {
 void BrowsePublicRecipes(){
  StackPanel body,actions;var w=Dialog("Recettes gratuites — bibliothèque",out body,out actions,820);w.Width=850;
  body.Children.Add(T("32 recettes adaptées de Wikibooks · sans produits laitiers · quantités et macros modifiables. L'import conserve vos recettes et aliments existants.",13,Muted));
  body.Children.Add(T("Valeurs alimentaires indicatives, à ajuster aux emballages. Pour le batch cooking, refroidissez rapidement, gardez au froid et congelez les portions des jours plus éloignés ; répéter un menu ne fixe pas sa durée de conservation.",12,Muted,new Thickness(0,10,0,10)));
  var filter=Combo(new[]{"Toutes","Petit-déjeuner","Plats","Végétarien","Batch cooking"},"Toutes");Field(body,"Afficher",filter);
  var selected=new HashSet<string>();var count=T("0 recette sélectionnée",13,Accent);body.Children.Add(count);var rows=new StackPanel();body.Children.Add(rows);
  var preview=SportNutrition.Copy(SN);var mapped=PublicNutritionLibrary.Import(preview,PublicNutritionLibrary.Recipes.Select(r=>r.Recipe.id));Action render=null;
  render=delegate{rows.Children.Clear();foreach(var entry in PublicNutritionLibrary.Recipes.Where(r=>Convert.ToString(filter.SelectedItem)=="Toutes"||(Convert.ToString(filter.SelectedItem)=="Petit-déjeuner"&&r.Recipe.meal=="Petit-déjeuner")||(Convert.ToString(filter.SelectedItem)=="Plats"&&r.Recipe.meal!="Petit-déjeuner")||(Convert.ToString(filter.SelectedItem)=="Végétarien"&&r.Vegetarian)||(Convert.ToString(filter.SelectedItem)=="Batch cooking"&&r.Batch))){var spec=entry;var recipe=preview.recipes.First(r=>r.id==mapped[spec.Recipe.id]);var row=new StackPanel();var check=new CheckBox{Content=recipe.name,IsChecked=selected.Contains(spec.Recipe.id),Margin=new Thickness(0,12,0,4)};check.Click+=delegate{if(check.IsChecked==true)selected.Add(spec.Recipe.id);else selected.Remove(spec.Recipe.id);count.Text=selected.Count+" recette(s) sélectionnée(s)";};row.Children.Add(check);row.Children.Add(T(MacroText(SportNutrition.RecipeServing(preview,recipe))+" / portion · "+recipe.portions+" portions",12,Muted));row.Children.Add(Btn("Voir la recette et sa source",delegate{ShowPublicRecipe(recipe,preview);},false,true));rows.Children.Add(row);}};filter.SelectionChanged+=delegate{render();};render();
  actions.Children.Add(Btn("Tout sélectionner",delegate{foreach(var r in PublicNutritionLibrary.Recipes)selected.Add(r.Recipe.id);count.Text=selected.Count+" recette(s) sélectionnée(s)";render();},false,true));
  SportDialogSave(w,body,actions,delegate{SportNutrition.Require(selected.Count>0,"Sélectionnez au moins une recette.");SportNutrition.Change(store,d=>PublicNutritionLibrary.Import(d,selected));},"Importer la sélection");
 }
 void ShowPublicRecipe(NutritionRecipe recipe,SportNutritionData data){StackPanel body,actions;var w=Dialog(recipe.name,out body,out actions,760);body.Children.Add(T(MacroText(SportNutrition.RecipeServing(data,recipe))+" / portion",16,Accent));foreach(var i in recipe.ingredients){var f=data.foods.First(x=>x.id==i.foodId);body.Children.Add(T(Fmt(i.quantity)+" "+f.unit+" · "+f.name,13));}body.Children.Add(T(recipe.instructions,12,Muted,new Thickness(0,16,0,0)));actions.Children.Add(Btn("Fermer",delegate{FinishFinanceDialog(w);},true));ShowWindow(w);}
 void ChoosePublicMenu(){StackPanel body,actions;var w=Dialog("Menus prêts à adapter",out body,out actions,520);body.Children.Add(T("Choisissez une sélection de recettes. La proposition ajuste les portions à vos objectifs et conserve vos repas déjà planifiés. Vous la vérifiez avant de l'ajouter.",13,Muted));foreach(string name in new[]{"Varié","Végétarien","Batch cooking"}){var pack=name;body.Children.Add(Btn(pack,delegate{PreviewPublicMenu(pack);},true));}actions.Children.Add(Btn("Fermer",delegate{FinishFinanceDialog(w);},false,true));ShowWindow(w);Refresh();}
 void PreviewPublicMenu(string pack){
  List<MenuEntry> proposed;var preview=SportNutrition.Copy(SN);try{PublicNutritionLibrary.Import(preview,PublicNutritionLibrary.Pack(pack));proposed=PublicNutritionLibrary.Suggest(SN,pack,menuStart,menuDays);}catch(Exception ex){MessageBox.Show(ex.Message);return;}
  StackPanel body,actions;var w=Dialog("Menu "+pack+" — proposition",out body,out actions,820);
  body.Children.Add(T("Les recettes nécessaires seront importées après validation. Les objectifs sont approchés, sans garantie d'égalité. Vérifiez les portions et les valeurs de vos ingrédients. Les menus restent séparés du journal consommé.",12,Muted));
  int existingMeals=SN.menu.Count(m=>Finance.Day(m.date)>=menuStart&&Finance.Day(m.date)<menuStart.AddDays(menuDays));
  body.Children.Add(T(existingMeals+" repas déjà prévus sur cette période. Sans remplacement, la proposition s'ajoute à ces repas et à leurs calories.",12,Accent,new Thickness(0,12,0,10)));
  var replace=new CheckBox{Content="Remplacer les repas prévus sur cette période",IsChecked=false};body.Children.Add(replace);
  foreach(var group in proposed.GroupBy(m=>m.date)){body.Children.Add(T(Finance.Day(group.Key).ToString("dd/MM/yyyy"),17,Ink,new Thickness(0,15,0,8)));body.Children.Add(T(MacroText(SportNutrition.Sum(group.Select(m=>SportNutrition.Scale(SportNutrition.RecipeServing(preview,preview.recipes.First(r=>r.id==m.recipeId)),m.servings)))),12,Accent));foreach(var m in group)body.Children.Add(T(m.meal+" · "+preview.recipes.First(r=>r.id==m.recipeId).name+" · "+Fmt(m.servings)+" portion(s)",12,Muted));}
  SportDialogSave(w,body,actions,delegate{SportNutrition.Change(store,d=>{PublicNutritionLibrary.Import(d,PublicNutritionLibrary.Pack(pack));if(replace.IsChecked==true)d.menu.RemoveAll(m=>Finance.Day(m.date)>=menuStart&&Finance.Day(m.date)<menuStart.AddDays(menuDays));d.menu.AddRange(proposed);});},"Enregistrer ce menu et ses recettes");
 }
}
